function validate([nums]) {
  if (nums.length < 1 || nums.length > 5000) return 'nums needs 1 to 5000 values.';
  if (nums.some(v => !Number.isInteger(v) || v === 0 || v < -1000 || v > 1000)) return 'Each value is a non-zero whole number between -1000 and 1000.';
  return null;
}

