function circularArrayLoop(nums) {
  const n = nums.length;
  const step = i => ((i + nums[i]) % n + n) % n;
  for (let i = 0; i < n; i++) {
    // After n jumps the walk is surely inside the cycle it ends in.
    let node = i;
    for (let t = 0; t < n; t++) node = step(node);
    // Collect that cycle and test its length and signs.
    const cycle = [node];
    for (let other = step(node); other !== node; other = step(other)) cycle.push(other);
    if (cycle.length > 1 && (cycle.every(j => nums[j] > 0) || cycle.every(j => nums[j] < 0))) return true;
  }
  return false;
}

