function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 10);
  const style = rand();
  const limit = style < 0.2 ? 1000 : style < 0.6 ? 3 : 1 + Math.floor(rand() * 12);
  const forward = rand();
  const nums = [];
  for (let i = 0; i < n; i++) {
    const magnitude = 1 + Math.floor(rand() * limit);
    // Lean towards one direction sometimes so that same-sign cycles appear often.
    const positive = forward < 0.25 ? rand() < 0.9 : forward < 0.5 ? rand() < 0.1 : rand() < 0.5;
    nums.push(positive ? magnitude : -magnitude);
  }
  return [nums];
}
